import java.util.*;

interface GameEntity {
    GameEntity cloneEntity(); // intentional: avoids Object.clone() semantics
}

final class Monster implements GameEntity {
    private int health;
    private final List<String> buffs; // owned mutable state
    private final PathfindingService nav; // shared service: never cloned

    Monster(int health, List<String> buffs, PathfindingService nav) {
        this.health = health;
        this.buffs = new ArrayList<>(buffs);
        this.nav = nav;
    }

    private Monster(Monster src) {
        this.health = src.health;
        this.buffs = new ArrayList<>(src.buffs); // deep: owned list
        this.nav = src.nav; // shared: service stays shared
    }

    @Override public Monster cloneEntity() { return new Monster(this); }

    public void addBuff(String b) { buffs.add(b); }
    public void setHealth(int h) { this.health = h; }
}

final class SpawnerRegistry {
    private final Map<String, GameEntity> exemplars = new HashMap<>();

    void register(String key, GameEntity e) { exemplars.put(key, e); }

    GameEntity spawn(String key) {
        GameEntity p = exemplars.get(key);
        if (p == null) throw new IllegalArgumentException("unknown: " + key);
        return p.cloneEntity(); // never return p itself
    }
}

import copy
from dataclasses import dataclass, field

@dataclass
class Character:
    name: str
    stats: dict              # owned mutable -> must be deep-copied
    renderer: object         # shared heavy service -> must stay shared

    def clone(self, *, deep_stats=True) -> "Character":
        # Explicit policy beats default copy.copy() / copy.deepcopy().
        # Trade-off: deepcopy(stats) costs time but buys isolation;
        # sharing renderer saves memory but requires thread-safety.
        stats = copy.deepcopy(self.stats) if deep_stats else self.stats
        return Character(self.name, stats, self.renderer)

# Registry holds exemplars, hands out copies only.
REGISTRY = {}
REGISTRY["orc"] = Character("orc", {"hp": 100, "atk": 12}, renderer=object())

def spawn(key: str, **overrides) -> Character:
    base = REGISTRY[key].clone()
    for k, v in overrides.items():
        setattr(base, k, v)
    return base
